import{_ as a,c as t,o as s,aB as i}from"./chunks/framework.C5UvI_iN.js";const d=JSON.parse('{"title":"Examples","description":"","frontmatter":{},"headers":[],"relativePath":"examples.md","filePath":"examples.md","lastUpdated":1789531156000}'),r={name:"examples.md"};function o(n,e,l,h,c,p){return s(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h1><p>These examples show how to set up a symbolic regression search and adapt it to your data, equation structure, or objective. If you are new to PySR, begin with Getting started. Otherwise, choose the topic that matches your task.</p><h2 id="getting-started" tabindex="-1"><a href="/PySR/v2.4.1/examples/getting-started">Getting started</a> <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;[Getting started](/examples/getting-started)&quot;">​</a></h2><ul><li><a href="/PySR/v2.4.1/examples/getting-started#simple-search">Simple search</a>: fit generated data and inspect the resulting expressions.</li><li><a href="/PySR/v2.4.1/examples/getting-started#custom-operator">Custom operator</a>: add an operator and define its symbolic export.</li><li><a href="/PySR/v2.4.1/examples/getting-started#multiple-outputs">Multiple outputs</a>: fit expressions for several target columns.</li><li><a href="/PySR/v2.4.1/examples/getting-started#plotting-an-expression">Plotting an expression</a>: export LaTeX and compare predictions with target values.</li><li><a href="/PySR/v2.4.1/examples/getting-started#feature-selection">Feature selection</a>: reduce the input variables considered by the search.</li><li><a href="/PySR/v2.4.1/examples/getting-started#denoising">Denoising</a>: smooth a noisy target with a Gaussian process before fitting expressions.</li></ul><h2 id="expression-specifications" tabindex="-1"><a href="/PySR/v2.4.1/examples/expression-specifications">Expression specifications</a> <a class="header-anchor" href="#expression-specifications" aria-label="Permalink to &quot;[Expression specifications](/examples/expression-specifications)&quot;">​</a></h2><ul><li><a href="/PySR/v2.4.1/examples/expression-specifications#expression-specifications">Expression specifications</a>: constrain equation structure and learn category-dependent parameters.</li><li><a href="/PySR/v2.4.1/examples/expression-specifications#recovering-a-magnetic-field-from-force-measurements">Recovering a magnetic field from force measurements</a>: supply the known force law in a template and search for its unknown functions.</li></ul><h2 id="objectives-and-losses" tabindex="-1"><a href="/PySR/v2.4.1/examples/objectives">Objectives and losses</a> <a class="header-anchor" href="#objectives-and-losses" aria-label="Permalink to &quot;[Objectives and losses](/examples/objectives)&quot;">​</a></h2><ul><li><a href="/PySR/v2.4.1/examples/objectives#custom-objectives">Custom objectives</a>: score complete candidate expressions with a Julia function.</li><li><a href="/PySR/v2.4.1/examples/objectives#writing-the-objective-in-python">Writing the objective in Python</a>: use a Python function to score candidates during the search.</li><li><a href="/PySR/v2.4.1/examples/objectives#swinging-up-a-cart-pole-with-a-rollout-objective">Swinging up a cart-pole with a rollout objective</a>: evaluate each candidate controller in a simulation.</li><li><a href="/PySR/v2.4.1/examples/objectives#inventing-a-pseudorandom-generator-with-no-target">Inventing a pseudorandom generator with no target</a>: score generators without observed target outputs.</li></ul><h2 id="physics-and-units" tabindex="-1"><a href="/PySR/v2.4.1/examples/physics">Physics and units</a> <a class="header-anchor" href="#physics-and-units" aria-label="Permalink to &quot;[Physics and units](/examples/physics)&quot;">​</a></h2><ul><li><a href="/PySR/v2.4.1/examples/physics#dimensional-constraints">Dimensional constraints</a>: attach physical units to the search problem.</li><li><a href="/PySR/v2.4.1/examples/physics#using-differential-operators">Using differential operators</a>: include derivatives in an expression template.</li><li><a href="/PySR/v2.4.1/examples/physics#discovering-a-pde">Discovering a PDE</a>: search for a differential equation using sampled field data.</li></ul><h2 id="search-behaviour" tabindex="-1"><a href="/PySR/v2.4.1/examples/search-behaviour">Search behaviour</a> <a class="header-anchor" href="#search-behaviour" aria-label="Permalink to &quot;[Search behaviour](/examples/search-behaviour)&quot;">​</a></h2><ul><li><a href="/PySR/v2.4.1/examples/search-behaviour#automatic-batching-on-a-large-dataset">Automatic batching on a large dataset</a>: evaluate candidates on batches drawn from the data.</li><li><a href="/PySR/v2.4.1/examples/search-behaviour#operators-of-any-arity">Operators of any arity</a>: supply operators that take more than two arguments.</li><li><a href="/PySR/v2.4.1/examples/search-behaviour#mutations-and-plugins">Mutations and plugins</a>: configure mutation weights and search plugins.</li><li><a href="/PySR/v2.4.1/examples/search-behaviour#adaptive-mutation-weights">Adaptive mutation weights</a>: adjust mutation choices as the search progresses.</li><li><a href="/PySR/v2.4.1/examples/search-behaviour#the-backsolve-mutation">The backsolve mutation</a>: derive targets for a replacement subtree from the operators above it.</li></ul><h2 id="instrumentation-and-workflow" tabindex="-1"><a href="/PySR/v2.4.1/examples/instrumentation">Instrumentation and workflow</a> <a class="header-anchor" href="#instrumentation-and-workflow" aria-label="Permalink to &quot;[Instrumentation and workflow](/examples/instrumentation)&quot;">​</a></h2><ul><li><a href="/PySR/v2.4.1/examples/instrumentation#using-tensorboard-for-logging">Using TensorBoard for logging</a>: log progress and metrics from the search for inspection in TensorBoard.</li><li><a href="/PySR/v2.4.1/examples/instrumentation#recording-the-genealogy-of-a-search">Recording the genealogy of a search</a>: inspect the relationships between expressions in a recorded search.</li><li><a href="/PySR/v2.4.1/examples/instrumentation#closing-an-agent-loop-with-guesses">Closing an agent loop with <code>guesses=</code></a>: supply candidate expressions as guesses for another search round.</li></ul><h2 id="value-types" tabindex="-1"><a href="/PySR/v2.4.1/examples/value-types">Value types</a> <a class="header-anchor" href="#value-types" aria-label="Permalink to &quot;[Value types](/examples/value-types)&quot;">​</a></h2><ul><li><a href="/PySR/v2.4.1/examples/value-types#complex-numbers">Complex numbers</a>: fit expressions to complex-valued data.</li><li><a href="/PySR/v2.4.1/examples/value-types#julia-packages-and-types">Julia packages and types</a>: use a Julia package inside a search operator.</li><li><a href="/PySR/v2.4.1/examples/value-types#custom-value-types">Custom value types</a>: define the values used by expressions and how PySR handles them.</li></ul><h2 id="beyond-numeric-values" tabindex="-1"><a href="/PySR/v2.4.1/examples/beyond-numeric-values">Beyond numeric values</a> <a class="header-anchor" href="#beyond-numeric-values" aria-label="Permalink to &quot;[Beyond numeric values](/examples/beyond-numeric-values)&quot;">​</a></h2><ul><li><a href="/PySR/v2.4.1/examples/beyond-numeric-values#breaking-an-affine-cipher-with-a-letter-type">Breaking an affine cipher with a letter type</a>: decode text with expressions that operate on letters.</li><li><a href="/PySR/v2.4.1/examples/beyond-numeric-values#rediscovering-conway-s-game-of-life">Rediscovering Conway&#39;s Game of Life</a>: learn the update rule from a finite table of cell transitions.</li><li><a href="/PySR/v2.4.1/examples/beyond-numeric-values#searching-over-machine-words">Searching over machine words</a>: build expressions from bitwise operations.</li><li><a href="/PySR/v2.4.1/examples/beyond-numeric-values#turtle-graphics-searching-over-drawings">Turtle graphics: searching over drawings</a>: search for a program that draws a target shape.</li><li><a href="/PySR/v2.4.1/examples/beyond-numeric-values#evolving-a-hopping-controller">Evolving a hopping controller</a>: replay a three-joint controller learned through simulated rollouts.</li></ul><p>See the <a href="/PySR/v2.4.1/options">Options section</a> for other ways to configure the search.</p>',19)])])}const m=a(r,[["render",o]]);export{d as __pageData,m as default};
